import {useState,useEffect,useRef,type ReactNode} from 'react';
import {LayoutDashboard,Building2,Users,Car,Wallet,FileText,Droplets,HeartHandshake,BarChart3,Bell,ShieldCheck,History,LogOut,Menu,X,Plus,Search,ArrowUpRight,ChevronLeft,ChevronRight,Download,Printer,Eye,EyeOff,Check,ArrowRight,Clock,CheckCircle2,AlertCircle,Settings,Loader2,Moon} from 'lucide-react';
