const feeNames:Row={FIXED:'Cố định / căn',AREA:'Theo diện tích',PERSON:'Theo số người',VEHICLE:'Phí gửi xe',ELECTRICITY:'Điện theo chỉ số',WATER:'Nước theo chỉ số'};
